<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { ElMessage, ElMessageBox } from 'element-plus'
import { ArrowLeft, Van, CircleCheck, CloseBold, RefreshLeft } from '@element-plus/icons-vue'
import { orderRepository } from '../data/repository'
import { canTransition, currency, shortDate } from '../utils'
import type { Order, OrderStatus } from '../types'

const route=useRoute(),router=useRouter(),order=ref<Order>(),shipDialog=ref(false),returnDialog=ref(false),shipment=reactive({carrier:'黑貓宅急便',trackingNumber:''}),returnReason=ref('')
const labels:Record<OrderStatus,string>={pending:'待付款',processing:'待出貨',shipped:'已出貨',completed:'已完成',cancelled:'已取消',returned:'已退貨'}
onMounted(async()=>{order.value=await orderRepository.get(String(route.params.id))})
const step=computed(()=>order.value?({pending:0,processing:1,shipped:2,completed:3,cancelled:0,returned:2}[order.value.status]):0)
async function transition(next:OrderStatus,label:string){if(!order.value||!canTransition(order.value.status,next)){ElMessage.error('此狀態無法執行該操作');return}order.value.status=next;order.value.logs.push({at:new Date().toISOString(),label});await orderRepository.save(JSON.parse(JSON.stringify(order.value)));ElMessage.success(label)}
async function ship(){if(!shipment.trackingNumber.trim()){ElMessage.warning('請輸入物流追蹤編號');return}if(!order.value)return;order.value.carrier=shipment.carrier;order.value.trackingNumber=shipment.trackingNumber;await transition('shipped','商品已出貨');shipDialog.value=false}
async function cancel(){await ElMessageBox.confirm('確定取消這筆訂單？','取消訂單',{type:'warning'});await transition('cancelled','訂單已取消')}
async function submitReturn(){if(!returnReason.value.trim()){ElMessage.warning('請填寫退貨原因');return}if(order.value)order.value.returnReason=returnReason.value;await transition('returned','退貨申請已建立');returnDialog.value=false}
</script>
<template>
  <section v-if="order" data-testid="order-detail">
    <button class="back-link" @click="router.push('/orders')"><el-icon><ArrowLeft/></el-icon>返回訂單列表</button>
    <Teleport to="#page-actions"><div class="actions"><el-button v-if="canTransition(order.status,'cancelled')" :icon="CloseBold" @click="cancel">取消訂單</el-button><el-button v-if="order.status==='processing'" type="primary" :icon="Van" data-testid="open-ship" @click="shipDialog=true">安排出貨</el-button><el-button v-if="order.status==='shipped'" type="success" :icon="CircleCheck" @click="transition('completed','訂單已完成')">完成訂單</el-button><el-button v-if="order.status==='shipped'" :icon="RefreshLeft" @click="returnDialog=true">申請退貨</el-button></div></Teleport>
    <article class="order-hero"><div><span>訂單編號</span><h2>{{order.id}}</h2><p>{{shortDate(order.createdAt)}} 建立</p></div><el-tag size="large" round>{{labels[order.status]}}</el-tag><strong>{{currency(order.total)}}</strong></article>
    <article class="progress-card"><el-steps :active="step" finish-status="success" align-center><el-step title="訂單成立"/><el-step title="付款完成"/><el-step title="商品出貨"/><el-step title="訂單完成"/></el-steps></article>
    <div class="detail-grid"><article class="panel items"><header><h3>訂單商品</h3><span>{{order.items.length}} 項商品</span></header><div v-for="item in order.items" :key="item.sku" class="item"><div class="item-img">{{item.name.slice(0,1)}}</div><div><strong>{{item.name}}</strong><span>{{item.sku}} · 數量 {{item.quantity}}</span></div><b>{{currency(item.price*item.quantity)}}</b></div><div class="total"><span>商品小計</span><b>{{currency(order.total)}}</b><span>運費</span><b>免運</b><strong>訂單總額</strong><em>{{currency(order.total)}}</em></div></article>
      <aside><article class="panel"><header><h3>顧客資訊</h3></header><div class="profile-card"><span>{{order.customerName.slice(0,1)}}</span><div><strong>{{order.customerName}}</strong><small>{{order.customerId}}</small></div></div><dl><dt>電子郵件</dt><dd>{{order.customerName.toLowerCase()}}@example.demo</dd><dt>收件地址</dt><dd>台北市信義區松高路 88 號</dd></dl></article><article v-if="order.carrier" class="panel"><header><h3>物流資訊</h3></header><dl><dt>物流商</dt><dd>{{order.carrier}}</dd><dt>追蹤編號</dt><dd class="tracking">{{order.trackingNumber}}</dd></dl></article></aside>
      <article class="panel timeline"><header><h3>訂單紀錄</h3></header><el-timeline><el-timeline-item v-for="log in [...order.logs].reverse()" :key="log.at" :timestamp="shortDate(log.at)" placement="top"><strong>{{log.label}}</strong></el-timeline-item></el-timeline></article>
    </div>
    <el-dialog v-model="shipDialog" title="安排訂單出貨" width="480"><el-form label-position="top"><el-form-item label="物流商"><el-select v-model="shipment.carrier"><el-option label="黑貓宅急便" value="黑貓宅急便"/><el-option label="新竹物流" value="新竹物流"/><el-option label="中華郵政" value="中華郵政"/></el-select></el-form-item><el-form-item label="物流追蹤編號 *"><el-input v-model="shipment.trackingNumber" data-testid="tracking-number" placeholder="輸入物流單號"/></el-form-item></el-form><template #footer><el-button @click="shipDialog=false">取消</el-button><el-button type="primary" data-testid="confirm-ship" @click="ship">確認出貨</el-button></template></el-dialog>
    <el-dialog v-model="returnDialog" title="建立退貨申請" width="480"><el-input v-model="returnReason" type="textarea" :rows="4" placeholder="請填寫退貨原因"/><template #footer><el-button @click="returnDialog=false">取消</el-button><el-button type="danger" @click="submitReturn">確認申請</el-button></template></el-dialog>
  </section>
</template>
<style scoped>
.back-link{display:flex;align-items:center;gap:6px;border:0;background:transparent;color:#68746c;margin:-60px 0 31px;cursor:pointer}.actions{display:flex;gap:8px}.order-hero{display:grid;grid-template-columns:1fr auto 150px;align-items:center;gap:22px;padding:22px 26px;background:#183626;color:white;border-radius:16px}.order-hero span,.order-hero p{font-size:11px;color:#a8bbae;margin:0}.order-hero h2{font-size:20px;margin:5px 0}.order-hero>strong{text-align:right;font-size:24px;color:#efc681}.progress-card,.panel{background:white;border:1px solid #e3e8e3;border-radius:16px}.progress-card{padding:26px;margin:16px 0}.detail-grid{display:grid;grid-template-columns:1.5fr .8fr;gap:16px}.panel{padding:21px}.panel header{display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid #edf0ec;padding-bottom:14px}.panel h3{font-size:15px;margin:0}.panel header span{font-size:11px;color:#8d968f}.item{display:grid;grid-template-columns:46px 1fr auto;gap:11px;align-items:center;padding:15px 0;border-bottom:1px solid #edf0ec}.item-img{display:grid;place-items:center;width:44px;height:44px;border-radius:11px;background:#e1ebe4;color:#35694b;font-weight:800}.item div:nth-child(2){display:grid}.item span{font-size:11px;color:#8c958e}.item b{font-size:13px}.total{margin:18px 0 0 auto;width:260px;display:grid;grid-template-columns:1fr auto;gap:9px;font-size:12px}.total span{color:#838d86}.total strong,.total em{border-top:1px solid #dfe5df;padding-top:12px}.total em{font-style:normal;font-size:18px;color:#2d6748;font-weight:800}.detail-grid aside{display:grid;gap:16px}.profile-card{display:flex;align-items:center;gap:10px;padding:16px 0}.profile-card>span{display:grid;place-items:center;width:40px;height:40px;border-radius:12px;background:#e4efe7;color:#2c6948;font-weight:800}.profile-card div{display:grid}.profile-card small{color:#939b95}.panel dl{display:grid;grid-template-columns:80px 1fr;gap:10px;margin:5px 0;font-size:12px}.panel dt{color:#8c958e}.panel dd{margin:0;text-align:right}.tracking{color:#2d6748;font-weight:800}.timeline{grid-column:1/-1}.timeline :deep(.el-timeline){padding-left:5px;margin-top:22px}@media(max-width:900px){.detail-grid{grid-template-columns:1fr}.order-hero{grid-template-columns:1fr auto}.order-hero>strong{grid-column:1/-1;text-align:left}.back-link{margin:0 0 20px}}
</style>
